SELECT c.acquisition_source, AVG(CASE WHEN EXISTS (SELECT 1 FROM orders o2 WHERE o2.customer_id = c.customer_id AND o2.is_deleted = FALSE AND o2.status IN ('delivered', 'in_transit', 'returned') AND o2.order_at > fo.first_at AND o2.order_at <= fo.first_at + INTERVAL 90 DAY) THEN 1.0 ELSE 0.0 END) AS r FROM customers c JOIN (SELECT customer_id, MIN(order_at) AS first_at FROM orders WHERE is_deleted = FALSE AND status IN ('delivered', 'in_transit', 'returned') GROUP BY 1) fo ON fo.customer_id = c.customer_id WHERE c.is_deleted = FALSE AND c.acquisition_source IN (SELECT name FROM marketing_campaigns) GROUP BY 1 HAVING COUNT(*) >= 20 ORDER BY r DESC LIMIT 1
